 /** Split a template into text and tag tokens. See README.md. */
 export function tokenize(template: string): Token[] {
-  throw new Error("not implemented");
+  const tokens: Token[] = [];
+  let pos = 0;
+  while (pos < template.length) {
+    const open = template.indexOf("{{", pos);
+    if (open === -1) {
+      tokens.push({ kind: "text", text: template.slice(pos) });
+      break;
+    }
+    if (open > pos) {
+      tokens.push({ kind: "text", text: template.slice(pos, open) });
+    }
+    const raw = template.startsWith("{{{", open);
+    const delimiter = raw ? "}}}" : "}}";
+    const start = open + delimiter.length;
+    const close = template.indexOf(delimiter, start);
+    if (close === -1) {
+      throw new Error("unterminated tag");
+    }
+    tokens.push(parseTag(template.slice(start, close).trim(), raw));
+    pos = close + delimiter.length;
+  }
+  return tokens;
 }
+
+function parseTag(content: string, raw: boolean): Token {
+  if (raw) {
+    return { kind: "value", expr: content, raw: true };
+  }
+  if (content === "else") {
+    return { kind: "else" };
+  }
+  if (content === "/if") {
+    return { kind: "end" };
+  }
+  const condition = /^#if\s+(.+)$/.exec(content);
+  if (condition) {
+    return { kind: "if", path: condition[1] };
+  }
+  return { kind: "value", expr: content, raw: false };
+}
